! Usage:
!   #include "hipfort_hipsparse_interfaces.f90"  ! directly in any program unit (needs cpp:
!                                     ! the #ifdef guards below must be honoured)
!   use hipfort_hipsparse                         ! via the pre-built module

  use, intrinsic :: iso_c_binding
  implicit none

  interface

    !---------------------------------------------
    ! hipsparseGetErrorName
    !---------------------------------------------
    !>  \ingroup aux_module
    !>   \brief Return the string representation of a hipSPARSE status's matching backend status
    !>   enum name
    !>
    !>   \details
    !>   \p hipsparseGetErrorName takes a hipSPARSE status as input and first converts it to the
    !>   matching backend
    !>   status (either \p rocsparse_status or \p cusparseStatus_t). It then returns the string
    !>   representation of this status
    !>   enum name. If the status is not recognized, the function returns "Unrecognized status
    !>   code".
    !>
    !>   For example, \p hipsparseGetErrorName( `HIPSPARSE_STATUS_SUCCESS` ) on a system with a
    !>   rocSPARSE backend will
    !>   return \p rocsparse_status_success. On a system with a cuSPARSE backend this function would
    !>   return
    !>   \p CUSPARSE_STATUS_SUCCESS.
    function hipsparseGetErrorName(status) &
       result(GetErrorName) &
       bind(C, name="hipsparseGetErrorName")
       import :: HIPSPARSE_STATUS_SUCCESS, c_ptr
       integer(kind(HIPSPARSE_STATUS_SUCCESS)), value :: status
       type(c_ptr) :: GetErrorName
    end function hipsparseGetErrorName

    !---------------------------------------------
    ! hipsparseGetErrorString
    !---------------------------------------------
    !>  \ingroup aux_module
    !>   \brief Return the hipSPARSE status's matching backend status description as a string
    !>
    !>   \details
    !>   \p hipsparseGetErrorString takes a hipSPARSE status as input and first converts it to the
    !>   matching backend
    !>   status (either \p rocsparse_status or \p cusparseStatus_t). It then returns the string
    !>   description of this status.
    !>   If the status is not recognized, the function returns "Unrecognized status code".
    function hipsparseGetErrorString(status) &
       result(GetErrorString) &
       bind(C, name="hipsparseGetErrorString")
       import :: HIPSPARSE_STATUS_SUCCESS, c_ptr
       integer(kind(HIPSPARSE_STATUS_SUCCESS)), value :: status
       type(c_ptr) :: GetErrorString
    end function hipsparseGetErrorString

