      hipsparseScsrmm_rank_1,&
      hipsparseScsrmm_rank_1_cptr,&
      hipsparseScsrmm_full_rank,&
      hipsparseScsrmm_full_rank_cptr,&
      hipsparseScsrmm_typed
#endif
#endif
  end interface

  interface hipsparseDcsrmm
