    function hipsparseSgpsvInterleavedBatch_bufferSizeExt_(handle,algo,m,ds,dl,d,du,dw,x, &
        batchCount,pBufferSizeInBytes) &
        bind(c, name="hipsparseSgpsvInterleavedBatch_bufferSizeExt")
